<script setup lang="ts">
import { computed, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; import { getApiErrorMessage } from '../api'
const form=reactive({email:'lin@example.com',password:'password'}); const submitting=ref(false); const error=ref(''); const auth=useAuthStore(); const router=useRouter(); const route=useRoute(); const sessionExpired=computed(()=>route.query.reason==='session-expired')
async function submit(){ submitting.value=true; error.value=''; try { await auth.login(form.email,form.password); await router.push('/portal') } catch(cause) { error.value=getApiErrorMessage(cause) } finally { submitting.value=false } }
</script>
<template><main class="portal-login"><section class="portal-login-panel"><div class="portal-brand portal-brand--dark"><span class="brand-mark">C</span>Cyberboard</div><p class="eyebrow">USER PORTAL</p><h1>登录用户中心</h1><p>查看套餐、订阅链接和流量使用情况。</p><p v-if="sessionExpired" class="session-notice" role="status">登录状态已过期，请重新登录。</p><form @submit.prevent="submit"><label>邮箱<input v-model="form.email" type="email" required :disabled="submitting" /></label><label>密码<input v-model="form.password" type="password" required :disabled="submitting" /></label><p v-if="error" class="form-error" role="alert">{{ error }}</p><button class="primary-button" type="submit" :disabled="submitting">{{ submitting?'正在验证…':'登录' }}</button></form><small>开发期提示：登录由控制面 API 验证，成功后会在本地保存会话令牌。</small></section></main></template>
